"""Word frequency counter — has 3 bugs."""
import re
from collections import Counter


class WordCounter:
    def __init__(self):
        self._counts: Counter = Counter()

    def add_text(self, text: str) -> None:
        """Count words in text, merging into existing counts.
        Words are case-insensitive; punctuation is stripped.
        """
        # BUG 1: does not lowercase — 'Hello' and 'hello' counted separately
        words = text.split()
        for word in words:
            # BUG 2: strips punctuation incorrectly — uses assignment instead of cleaned
            cleaned = re.sub(r"[^a-zA-Z0-9']", "", word)
            self._counts[word] += 1  # BUG: should use cleaned, not word

    def count(self, word: str) -> int:
        """Return frequency of word (case-insensitive)."""
        # BUG 3: does not lowercase the lookup
        return self._counts.get(word, 0)

    def most_common(self, n: int) -> list[tuple[str, int]]:
        """Return the n most common words as (word, count) pairs."""
        raise NotImplementedError

    def total(self) -> int:
        """Return total word count across all words."""
        return sum(self._counts.values())
